H.background();
const m = Math.max(0.1, P.mass), vel = P.vel;
// Momentum p = m * v.  A cart of mass m glides at speed v across a track,
// looping back so it stays in frame.  Its velocity arrow length and the
// momentum bar both scale with p = m*v.
const p = m * vel;
const w = H.W, h = H.H;
H.text("Momentum: p = m · v", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m.toFixed(1) + " kg   v = " + vel.toFixed(1) + " m/s   →   p = " + p.toFixed(1) + " kg·m/s", 24, 52, { color: H.colors.sub, size: 13 });
// Track line.
const trackY = h * 0.55;
H.line(40, trackY, w - 40, trackY, { color: H.colors.axis, width: 2 });
// Cart loops across the track (wrap motion, never drifts off).
const span = w - 120;
const cx = 60 + ((vel * 40 * t) % span + span) % span;
// Cart size grows a touch with mass so heavier = visibly bigger.
const cw = 30 + m * 6, ch = 18 + m * 3;
H.rect(cx - cw / 2, trackY - ch, cw, ch, { fill: H.colors.accent, stroke: H.colors.ink, width: 1.5, radius: 4 });
H.circle(cx - cw / 4, trackY, 5, { fill: H.colors.sub });
H.circle(cx + cw / 4, trackY, 5, { fill: H.colors.sub });
// Velocity arrow from the cart, length proportional to v (direction = sign of v).
const dir = vel >= 0 ? 1 : -1;
H.arrow(cx, trackY - ch - 14, cx + dir * (20 + Math.abs(vel) * 8), trackY - ch - 14, { color: H.colors.good, width: 3 });
H.text("v", cx + dir * 20, trackY - ch - 22, { color: H.colors.good, size: 13 });
// Momentum bar at the bottom: length proportional to p.
const barY = h * 0.82, barX = 60;
H.text("p = m·v", barX, barY - 14, { color: H.colors.sub, size: 12 });
H.rect(barX, barY, Math.min(Math.abs(p) * 10, w - 120), 16, { fill: H.colors.warn, radius: 3 });
H.text(p.toFixed(1) + " kg·m/s", barX + Math.min(Math.abs(p) * 10, w - 120) + 8, barY + 13, { color: H.colors.ink, size: 12 });
H.legend([{ label: "velocity v", color: H.colors.good }, { label: "momentum p", color: H.colors.warn }], w - 180, 28);
